import { SystemProgram, TransactionInstruction } from "@solana/web3.js";
import { POWERCHAIN_FEE_WALLET_ADDRESS, SOLANA_TOKEN_2022_PROGRAM_ID } from "@powerchain/launchpad-config";
import { asKey, deriveParticipantPda, deriveSalePda, deriveVaultAuthorityPda } from "./pda.js";
import { encodeClaim, encodeInitializeSale, encodeNoArgs, encodePurchase, encodeSetPaused, encodeUpdateTiming } from "./codec.js";
function meta(pubkey, isSigner = false, isWritable = false) { return { pubkey: asKey(pubkey), isSigner, isWritable }; }
function unix(value) { const ms = value instanceof Date ? value.getTime() : Date.parse(value); if (!Number.isFinite(ms))
    throw new Error("invalid_timestamp"); return BigInt(Math.floor(ms / 1000)); }
export function eligibilityCode(value) { return value === "public" ? 0 : value === "allowlist" ? 1 : 2; }
export function buildInitializeSaleInstruction(input) {
    const programId = asKey(input.programId);
    const sale = deriveSalePda({ programId, creator: input.creatorWallet, mint: input.mint, saleId: input.saleId });
    const vaultAuthority = deriveVaultAuthorityPda(programId, sale.address);
    const data = encodeInitializeSale({ saleSeed: sale.seed, decimals: input.decimals, eligibility: eligibilityCode(input.eligibility), vestingEnabled: input.vestingEnabled, deliveryOnClaim: input.deliveryMode === "claim", quoteAuthority: asKey(input.quoteAuthorityWallet).toBytes(), startsAt: unix(input.startsAt), endsAt: unix(input.endsAt), claimStartsAt: unix(input.claimStartsAt), vestingCliffAt: unix(input.vestingCliffAt), vestingEndsAt: unix(input.vestingEndsAt), allocationBaseUnits: input.allocationBaseUnits, priceUsdMicros: input.priceUsdMicros, minPurchaseUsdMicros: input.minPurchaseUsdMicros, maxPurchaseUsdMicros: input.maxPurchaseUsdMicros });
    return { salePda: sale.address, vaultAuthorityPda: vaultAuthority.address, instruction: new TransactionInstruction({ programId, keys: [meta(input.creatorWallet, true, true), meta(sale.address, false, true), meta(input.mint), meta(input.sourceVaultTokenAccount, false, true), meta(vaultAuthority.address), meta(input.paymentReceiverWallet), meta(POWERCHAIN_FEE_WALLET_ADDRESS), meta(SOLANA_TOKEN_2022_PROGRAM_ID), meta(SystemProgram.programId)], data }) };
}
export function buildAdoptVaultAuthorityInstruction(input) { const programId = asKey(input.programId), vaultAuthority = deriveVaultAuthorityPda(programId, input.salePda); return { vaultAuthorityPda: vaultAuthority.address, instruction: new TransactionInstruction({ programId, keys: [meta(input.currentVaultAuthority, true), meta(input.salePda), meta(input.sourceVaultTokenAccount, false, true), meta(vaultAuthority.address), meta(SOLANA_TOKEN_2022_PROGRAM_ID)], data: encodeNoArgs("adoptVaultAuthority") }) }; }
export function buildPurchaseInstruction(input) { const programId = asKey(input.programId), participant = deriveParticipantPda(programId, input.salePda, input.wallet), vaultAuthority = deriveVaultAuthorityPda(programId, input.salePda); return { participantPda: participant.address, vaultAuthorityPda: vaultAuthority.address, instruction: new TransactionInstruction({ programId, keys: [meta(input.wallet, true, true), meta(input.quoteAuthorityWallet, true, false), meta(input.salePda, false, true), meta(participant.address, false, true), meta(input.sourceVaultTokenAccount, false, true), meta(vaultAuthority.address), meta(input.destinationTokenAccount, false, true), meta(input.mint), meta(input.paymentReceiverWallet, false, true), meta(POWERCHAIN_FEE_WALLET_ADDRESS, false, true), meta(SOLANA_TOKEN_2022_PROGRAM_ID), meta(SystemProgram.programId)], data: encodePurchase({ tokenAmountBaseUnits: input.tokenAmountBaseUnits, paymentLamports: input.paymentLamports, serviceFeeLamports: input.serviceFeeLamports, purchaseNonce: input.purchaseNonce }) }) }; }
export function buildClaimInstruction(input) { const programId = asKey(input.programId), participant = deriveParticipantPda(programId, input.salePda, input.wallet), vaultAuthority = deriveVaultAuthorityPda(programId, input.salePda); return { participantPda: participant.address, vaultAuthorityPda: vaultAuthority.address, instruction: new TransactionInstruction({ programId, keys: [meta(input.wallet, true), meta(input.salePda, false, true), meta(participant.address, false, true), meta(input.sourceVaultTokenAccount, false, true), meta(vaultAuthority.address), meta(input.destinationTokenAccount, false, true), meta(input.mint), meta(SOLANA_TOKEN_2022_PROGRAM_ID)], data: encodeClaim(input.amountBaseUnits) }) }; }
export function buildSetPausedInstruction(input) { return new TransactionInstruction({ programId: asKey(input.programId), keys: [meta(input.creatorWallet, true), meta(input.salePda, false, true)], data: encodeSetPaused(input.paused) }); }
export function buildUpdateTimingInstruction(input) { return new TransactionInstruction({ programId: asKey(input.programId), keys: [meta(input.creatorWallet, true), meta(input.salePda, false, true)], data: encodeUpdateTiming({ startsAt: unix(input.startsAt), endsAt: unix(input.endsAt), claimStartsAt: unix(input.claimStartsAt), vestingCliffAt: unix(input.vestingCliffAt), vestingEndsAt: unix(input.vestingEndsAt) }) }); }
export function buildLifecycleInstruction(input) { return new TransactionInstruction({ programId: asKey(input.programId), keys: [meta(input.creatorWallet, true), meta(input.salePda, false, true)], data: encodeNoArgs(input.action === "cancel" ? "cancelSale" : "completeSale") }); }
